target.css:
:root {
  --ink: #1d2933;
  --muted: #667786;
  --paper: #fffdf7;
  --navy: #173b55;
  --blue: #4a8fb5;
  --gold: #e6af45;
  --line: #d9e1df;
  --mint: #dff0e8;
  --coral: #c85d54;
}

.chime-panel {
  box-sizing: border-box;
  width: 500px;
  padding: 16px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-top: 5px solid var(--navy);
  border-radius: 14px;
  color: var(--ink);
}

.panel-header,
.panel-footer,
.sequence-heading,
.cue-list li {
  display: flex;
  align-items: center;
}

.panel-header {
  justify-content: space-between;
  margin-bottom: 12px;
}

.heading-group p,
h1,
h2,
.clock-card figcaption,
.panel-footer p {
  margin: 0;
}

.eyebrow {
  color: var(--blue);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1.1px;
  text-transform: uppercase;
}

h1 {
  margin-top: 2px;
  color: var(--navy);
  font-size: 21px;
  line-height: 1.1;
}

.live-status {
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--navy);
  font-size: 12px;
  font-weight: 800;
}

.main-grid {
  display: grid;
  grid-template-columns: 138px 1fr;
  gap: 12px;
}

.clock-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin: 0;
  padding: 10px;
  background: var(--navy);
  border-radius: 10px;
}

.clock-face {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 78px;
  height: 78px;
  border: 4px solid var(--gold);
  border-radius: 50%;
  color: var(--paper);
}

.clock-face::before,
.clock-face::after {
  position: absolute;
  content: "";
  background: var(--gold);
  border-radius: 2px;
}

.clock-face::before {
  width: 4px;
  height: 8px;
  top: 4px;
}

.clock-face::after {
  width: 8px;
  height: 4px;
  right: 4px;
}

.clock-face b {
  font-size: 16px;
  letter-spacing: .4px;
}

.hand {
  position: absolute;
  bottom: 50%;
  left: 50%;
  width: 3px;
  transform-origin: bottom;
  background: var(--coral);
  border-radius: 3px;
}

.hour-hand {
  height: 20px;
  transform: rotate(232deg);
}

.minute-hand {
  height: 28px;
  transform: rotate(132deg);
}

.clock-card figcaption {
  margin-top: 8px;
  color: var(--paper);
  font-size: 11px;
  font-weight: 700;
}

.sequence-card {
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
}

.sequence-heading {
  justify-content: space-between;
  padding-bottom: 7px;
  border-bottom: 1px solid var(--line);
}

h2 {
  color: var(--navy);
  font-size: 14px;
}

.sequence-heading span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.cue-list {
  display: grid;
  gap: 2px;
  margin: 6px 0 0;
  padding: 0;
  list-style: none;
}

.cue-list li {
  gap: 8px;
  min-height: 22px;
  font-size: 12px;
}

.cue-time {
  width: 38px;
  color: var(--blue);
  font-size: 11px;
  font-weight: 800;
}

.cue-list strong {
  flex: 1;
  font-size: 12px;
}

.cue-list em {
  color: var(--muted);
  font-size: 11px;
  font-style: normal;
}

.panel-footer {
  justify-content: space-between;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
}

.panel-footer p {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}

.signal-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--blue);
}

button {
  padding: 7px 12px;
  border: 0;
  border-radius: 7px;
  background: var(--gold);
  color: var(--navy);
  font-size: 12px;
  font-weight: 800;
}

